:root {
  color-scheme: light;
  --paper: #f8f2e6;
  --ink: #30241b;
  --accent: #69352a;
  --border: #c8b69e;
  --panel: #fffaf2;
}
* { box-sizing: border-box; }
[hidden] { display: none; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 1rem/1.45 system-ui, sans-serif; }
main { max-width: 54rem; padding: clamp(.85rem, 3vw, 1.65rem); margin: auto; }
header { border-bottom: 1px solid var(--border); padding-bottom: .7rem; margin-bottom: .8rem; }
h2, h3 { margin: 0; font: 600 1.85rem/1.1 Georgia, serif; }
header p, #note { margin: .4rem 0 0; }
label { display: block; font-weight: 650; margin-bottom: .3rem; }
.controls { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: .4rem; }
input, button { min-height: 2.55rem; border: 1px solid var(--border); border-radius: .3rem; padding: .38rem .65rem; font: inherit; }
input { min-width: 0; background: var(--panel); color: var(--ink); }
button { cursor: pointer; background: var(--accent); color: white; }
button.secondary, .examples button { background: var(--panel); color: var(--accent); }
button:hover { text-decoration: underline; }
:focus-visible { outline: 2px solid #315d50; outline-offset: 2px; }
.examples { display: flex; flex-wrap: wrap; gap: .35rem; margin-top: .55rem; }
.examples button { font: 1.05rem/1.2 Georgia, serif; }
.result { margin-top: .8rem; border: 1px solid var(--border); border-left: .25rem solid var(--accent); border-radius: .35rem; background: var(--panel); padding: .75rem; }
#group, #pattern, h4 { margin: 0; font-weight: 700; }
#group { color: var(--accent); font-size: .87rem; }
#match { margin: .3rem 0; overflow-wrap: anywhere; }
#related { margin-top: .75rem; border-top: 1px solid var(--border); padding-top: .6rem; }
@media (max-width: 27rem) {
  .controls { grid-template-columns: 1fr 1fr; }
  input { grid-column: 1 / -1; }
}

