    return;
  }
  const entry = index.get(key);
  if (!entry) {
    showEmpty("This word is outside the example list. Try one of the Greek words above.");
    return;
  }
  const [spelling, kind, finalAcute, detail] = entry;
  group.textContent = groups[kind];
  match.textContent = spelling;
  pattern.textContent = finalAcute ? "Acute on the final syllable" : "Accent before the final syllable";
