  const contrasting = peers.filter((other) => Boolean(other[2]) !== Boolean(finalAcute));
  const similar = peers.filter((other) => Boolean(other[2]) === Boolean(finalAcute));
  relatedWords.replaceChildren(...[...contrasting, ...similar].slice(0, 4).map((other) => compareButton(other[0])));
  related.hidden = false;
}

