const $ = (selector) => document.querySelector(selector);
const input = $("#inp");
const output = $("#outWord");
const rule = $("#rule");

const notes = {
  long: "Naturally long penult with a circumflex in Herodian’s one-form -θος examples.",
  closed: "The penult ends in a consonant and carries the acute in this -θος example.",
  final: "Final acute in Herodian’s group of three-gender or adverb-derived forms.",
};
const entries = [
  ["μῦθος", notes.long],
  ["Ζῆθος", notes.long],
  ["Ξοῦθος", notes.long],
  ["στρουθός", "Herodian marks the final acute as exceptional. Chaeiris reports a non-final Attic accent."],
  ["πεζός", notes.final],
  ["χθιζός", notes.final],
  ["πρωϊζός", notes.final],
  ["πτόρθος", notes.closed],
  ["γόνθος", notes.closed],
  ["μαζός", "Herodian marks it as exceptional because it has one form and a final acute."],
  ["Τίριζος", "Earlier accent in the name of a Paphlagonian people."],
  ["Κρόβυζος", "Earlier accent in the name of a people by the Ister."],
  ["Λόκοζος", "Earlier accent in the name of a Phrygian city."],
  ["Κάττουζος", "Earlier accent in the name of a Thracian people."],
  ["κῶθος", notes.long],
  ["Σῆθος", notes.long],
  ["Βοῦθος", notes.long],
  ["Νοῦθος", notes.long],
  ["Λῆθος", notes.long],
];

const greekWord = /(?:(?=\p{L})\p{Script=Greek}\p{M}*)+/gu;
const vowels = new Set("αεηιουω");
const diphthongs = new Set(["αι", "ει", "οι", "υι", "αυ", "ευ", "ου", "ηυ"]);
const accentMarks = /[\u0300\u0301\u0342]/g;

function lookupKey(text) {
  return text.normalize("NFD").toLowerCase().replace(/\p{M}/gu, "").replace(/ς/g, "σ");
}
const index = new Map(entries.map((entry) => [lookupKey(entry[0]), entry]));

function accentPosition(word, position) {
  const letters = word.normalize("NFD").match(/\p{L}\p{M}*/gu);
  const nuclei = [];
  for (let i = 0; i < letters.length; i++) {
    const vowel = letters[i][0].toLowerCase();
    if (!vowels.has(vowel)) continue;
    const following = letters[i + 1];
    if (following && !following.includes("\u0308") && !letters[i].includes("\u0345")
        && diphthongs.has(vowel + following[0].toLowerCase())) {
      i++;
    }
    nuclei.push(i);
  }
  const target = nuclei.at(-position);
  if (target === undefined) return null;
  const shifted = letters.map((letter) => letter.replace(accentMarks, ""));
  const cluster = shifted[target];
  shifted[target] = cluster.endsWith("\u0345")
    ? cluster.slice(0, -1) + "\u0301\u0345"
    : cluster + "\u0301";
  return shifted.join("").normalize("NFC");
}

const positions = {ultima: 1, penult: 2, antepenult: 3};
const emptyNote = "Enter a Greek example or choose one of the examples.";

function run(force) {
  if (!input.value.trim()) {
    output.textContent = "—";
    rule.textContent = emptyNote;
    return;
  }
  const feedback = [];
  const result = input.value.replace(greekWord, (word) => {
    if (force) {
      const accented = accentPosition(word, positions[force]);
      feedback.push(accented
        ? word + " — sandbox acute on the " + force + "."
        : word + " — too few syllables for the " + force + ".");
      return accented ?? word;
    }
    const example = index.get(lookupKey(word));
    feedback.push(example
      ? example[0] + " — " + example[1]
      : word + " — outside the example list.");
    return example ? example[0] : word;
  });

  output.textContent = feedback.length ? result : "—";
  rule.textContent = feedback.length ? feedback.join("\n") : emptyNote;
}

for (const [spelling] of entries.slice(0, 11)) {
  const button = document.createElement("button");
  button.className = "chip";
  button.type = "button";
  button.lang = "grc";
  button.textContent = spelling;
  button.addEventListener("click", () => {
    input.value = spelling;
    run();
    input.focus();
  });
  $("#chips").append(button);
}
$("#btn").addEventListener("click", () => run());
input.addEventListener("keydown", (event) => {
  if (event.key === "Enter" && !event.isComposing) run();
});
$("#clear").addEventListener("click", () => {
  input.value = "";
  run();
  input.focus();
});
for (const button of document.querySelectorAll("button[data-force]")) {
  button.addEventListener("click", () => run(button.dataset.force));
}

input.value = "μυθος";
run();

